
// ───────── 스크린샷으로 불러오기 (claude.use("sample") + 이미지) ─────────
// 캐릭터 상세(장비 미장착) · 장비 변경 · 보스 스탯 화면을 읽어 값과 장비를 채운다.
let shotSample = null, shotFiles = [], shotModel = null, shotCtl = null;
const SHOT_PROMPT = `다음 이미지들은 모바일 게임 「어나더 에덴」의 화면 캡처입니다. 각 이미지가 어떤 화면인지 분류하고, 화면에 실제로 보이는 글자와 숫자만 읽어 JSON 하나로 답하세요. 보이지 않거나 확실하지 않은 값은 null로 두고 절대 추측하지 마세요.

화면 종류:
- "stats": '캐릭터 상세' 화면. 캐릭터 이름(왼쪽 위 큰 글자), HP/MP(최대값, 슬래시 오른쪽), 공격·마력·방어·마방, 힘·지능·내구·속도·행운·정신, 천명(소용돌이 아이콘 옆 숫자, 보통 0~255), 아래쪽 장비 칸 4줄의 글자(장착 안 했으면 "미장착").
- "equip": '장비 변경' 화면. 왼쪽 스테이터스(물리 공격·마법 공격·물리 방어·마법 방어는 괄호 앞 숫자, HP·MP·힘·지능·내구·정신·속도·행운). 오른쪽 장비 칸은 이 배치입니다:
    1줄: [무기] [방어구]
    2줄: [배지1] [배지2]
    3줄: [글래스터1] [글래스터2]
    4줄: [글래스터3] [글래스터4]
    맨 아래 '특수 글래스터' 띠: [전용 글래스터]
  각 칸의 장비 이름을 해당 키에 넣고, 글래스터 칸은 이름 아래 작은 글씨의 광석 이름도 함께 넣으세요. 빈 칸(+ 표시만 있음)은 null.
- "boss": 전투 화면 위쪽의 적 스탯 창. HP 최대값(슬래시 오른쪽), 힘·지능·속도·내구·정신·행운.
- "other": 그 밖의 화면.

이름은 화면에 쓰인 그대로(꺾쇠 < > 포함) 적으세요. 숫자는 쉼표 없이 정수로 적으세요.

이 형식으로만 답하세요:
{"images":[{"index":1,"type":"stats","stats":{"name":"미나르카","hp":6478,"mp":758,"atk":328,"mag":209,"def":287,"mdef":258,"str":328,"int":209,"end":287,"spd":294,"luck":220,"spr":258,"fate":255,"slots":["미장착","미장착","미장착","미장착"]}},
{"index":2,"type":"equip","equip":{"weapon":"…","armor":"…","badge1":null,"badge2":"…","glaster1":null,"glaster2":{"name":"…","ore":"…"},"glaster3":null,"glaster4":null,"special":"…","patk":630,"matk":259,"pdef":523,"mdef":462,"hp":6578,"mp":873,"str":388,"int":229,"end":283,"spr":245,"spd":411,"luck":240}},
{"index":3,"type":"boss","boss":{"hp":48299999,"str":228,"int":228,"spd":15,"end":397,"spr":397,"luck":122}}]}
위 숫자와 이름은 형식 예시일 뿐입니다. 이미지 순서대로 index를 1부터 매기세요.`;

const nz = v => (v === null || v === undefined || v === '' || isNaN(+v)) ? null : Math.round(+v);
const normN = t => String(t || '').replace(/\s+/g, '').replace(/[〈＜]/g, '<').replace(/[〉＞]/g, '>').toLowerCase();

// 장비 이름 → 데이터 매칭
function matchWeapon(name, atk, mag) {
  const k = normN(name); if (!k) return { id: null, opts: [] };
  let opts = DATA.w.filter(w => normN(w.n) === k);
  if (!opts.length) opts = DATA.w.filter(w => normN(w.n).startsWith(k) || k.startsWith(normN(w.n).replace(/\(.*?\)$/, '')));
  const inR = (v, x, lo, hi) => hi !== undefined ? v >= lo && v <= hi : v === x;   // 범위 표기 무기는 범위 안이면 일치
  const exact = opts.filter(w => atk !== null && inR(atk, w.atk, w.atkMin, w.atkMax) && (mag === null || inR(mag, w.mag, w.magMin, w.magMax)));
  const pick = exact[0] || opts[0];
  return { id: pick ? pick.id : null, opts: opts.map(w => w.id), sure: !!exact[0] || opts.length === 1 };
}
function matchSimple(list, name) {
  const k = normN(name); if (!k) return { id: null, opts: [] };
  let opts = list.filter(x => normN(x.n) === k);
  if (!opts.length) opts = list.filter(x => normN(x.n).startsWith(k) || k.startsWith(normN(x.n)));
  return { id: opts[0] ? opts[0].id : null, opts: opts.map(x => x.id), sure: opts.length === 1 };
}
function matchGlaster(name, wt, special) {
  let raw = String(name || '').trim(); if (!raw) return { id: null, opts: [] };
  // 증표: 극 ○○의 증표 / 진 ○○의 증표 / ○○의 증표 → 시트의 클래스 증표
  if (/의\s*증표$/.test(raw) && !/수호성/.test(raw)) raw = /^극\s/.test(raw) ? '극 (5★ 클래스)의 증표' : /^진\s/.test(raw) ? '진 (5★ 클래스)의 증표' : '(5★ 클래스)의 증표';
  const m = raw.match(/^(.*?)\s*(<[^>]+>)\s*$/), base = normN(m ? m[1] : raw), cond = m ? m[2] : '';
  const all = DATA.gl.filter(g => normN(g.n) === base);
  let opts = cond ? all.filter(g => g.conds.includes(cond) || `<${g.wt}>` === cond) : all;
  if (!opts.length) opts = all;
  if (!cond && wt) { const byWt = opts.filter(g => !g.wt || g.wt === wt); if (byWt.length) opts = byWt; }
  if (special !== undefined) { const sp = opts.filter(g => special ? (g.ck === 'char' || g.sp) : !(g.ck === 'char' || g.sp)); if (sp.length) opts = sp; }
  return { id: opts[0] ? opts[0].id : null, opts: opts.map(g => g.id), sure: opts.length === 1 };
}
function matchOre(name, g) {
  const k = normN(name); if (!k) return g && g.pot ? 'pot' : '';
  if (k.includes('잠재')) return 'pot';
  const o = Object.values(ORES).find(o => o.id && normN(o.n) === k) || Object.values(ORES).find(o => o.id && o.id !== 'pot' && (normN(o.n).startsWith(k) || k.startsWith(normN(o.n))));
  return o ? o.id : '';
}

// 지정한 장비 조합이 주는 스탯 합 (페이지 계산과 같은 규칙)
// bv: 사진 확인 창에서 입력한 배지 스탯 { badge1: [{s,v}], badge2: [...] } — 이름만 있는 배지·반복 획득 배지 몫
function equipStatBonus(plan, s, bv) {
  bv = bv || {};
  const save = { equip: Object.assign({}, equip), ore: Object.assign({}, ore), bval: badgeVal };
  const pe = Object.assign({}, plan.equip), cust = [];
  ['badge1', 'badge2'].forEach(k => { if (pe[k] === 'custom') { pe[k] = null; cust.push(k); } });
  Object.assign(equip, pe); Object.assign(ore, plan.ore);
  badgeVal = { badge1: (bv.badge1 || []).map(r => ({ s: r.s, v: +r.v || 0 })), badge2: (bv.badge2 || []).map(r => ({ s: r.s, v: +r.v || 0 })) };
  const sum = { str: 0, int: 0, spd: 0, luck: 0, mp: 0, end: 0, spr: 0 };
  try {
    for (const it of itemsWith(null, null, s)) for (const e of it.fx || []) {
      if (e.k === 'stat' && sum[e.s] !== undefined && (SOL_STAT(e.s) || interpret(e, s, PHYS.includes(s.kind))[1])) sum[e.s] += Math.floor(fv(e.v, s));
    }
    // badgeWithVals는 대미지 관련 스탯만 넣으므로 MP 등은 직접 더함
    ['badge1', 'badge2'].forEach(k => { if (equip[k] && badgeVarKeys(ITEMS[equip[k]])) (bv[k] || []).forEach(r => { if (sum[r.s] !== undefined && !BADGE_DMG.includes(r.s)) sum[r.s] += +r.v || 0; }); });
    cust.forEach(k => (bv[k] || []).forEach(r => { if (sum[r.s] !== undefined) sum[r.s] += +r.v || 0; }));
  } finally { Object.assign(equip, save.equip); Object.assign(ore, save.ore); badgeVal = save.bval; }
  return sum;
}

const SHOT_FIELDS = [['str', '힘'], ['int', '지능'], ['spd', '속도'], ['luck', '행운'], ['mp', '최대 MP'], ['fate', '천명']];
const BOSS_FIELDS = [['tdef', '방어 (내구)', 'end'], ['tmdef', '마방 (정신)', 'spr']];

function buildShotModel(res, bvIn) {
  const imgs = (res && Array.isArray(res.images)) ? res.images : [];
  const st = (imgs.find(i => i && i.type === 'stats') || {}).stats || null;
  const eq = (imgs.find(i => i && i.type === 'equip') || {}).equip || null;
  const bs = (imgs.find(i => i && i.type === 'boss') || {}).boss || null;
  const M = { warn: [], info: [], rows: [], equipRows: [], custom: null, stats: st, eq, bs };
  const s = S(); if (st && nz(st.fate) !== null) s.fate = nz(st.fate);
  if (!st && !eq && !bs) { M.warn.push('캐릭터 상세 · 장비 변경 · 보스 스탯 화면을 찾지 못했습니다. 다른 캡처로 다시 시도해 주세요.'); return M; }
  // 캐릭터 상세: 장비가 장착돼 있으면 경고
  if (st) {
    const slots = Array.isArray(st.slots) ? st.slots : [];
    const worn = slots.some(x => x && !/미장착/.test(String(x))) || (nz(st.atk) !== null && nz(st.str) !== null && nz(st.atk) !== nz(st.str));
    if (worn) M.warn.push('캐릭터 상세 화면에 장비가 장착되어 있습니다. 해제하세요. (장비 스탯이 섞여 있어 캐릭터 스탯이 실제보다 높게 들어갑니다)');
  }
  // 장비 매칭
  let plan = null;
  if (eq) {
    plan = { equip: { weapon: null, armor: null, badge1: null, badge2: null, g1: null, g2: null, g3: null, g4: null, gs: null }, ore: { g1: '', g2: '', g3: '', g4: '', gs: '' } };
    const pAtk = nz(eq.patk), pMag = nz(eq.matk), sStr = nz(eq.str), sInt = nz(eq.int);
    const w = matchWeapon(eq.weapon, pAtk !== null && sStr !== null ? pAtk - sStr : null, pMag !== null && sInt !== null ? pMag - sInt : null);
    const wt = w.id ? ITEMS[w.id].t : null;
    const rows = [['weapon', '무기', eq.weapon, w]];
    rows.push(['armor', '방어구', eq.armor, matchSimple(DATA.armor, eq.armor)]);
    const bd = Array.isArray(eq.badges) ? eq.badges : [eq.badge1, eq.badge2];
    [0, 1].forEach(i => rows.push(['badge' + (i + 1), '배지 ' + (i + 1), bd[i], matchSimple(DATA.badges, bd[i])]));
    const gls = Array.isArray(eq.glasters) ? eq.glasters : [eq.glaster1, eq.glaster2, eq.glaster3, eq.glaster4];
    [0, 1, 2, 3].forEach(i => { const g = gls[i]; rows.push(['g' + (i + 1), '글래스터 ' + (i + 1), g && g.name, matchGlaster(g && g.name, wt, false), g && g.ore]); });
    rows.push(['gs', '전용 글래스터', eq.special, matchGlaster(eq.special, wt, true)]);
    let unknownBadge = null;
    for (const [k, label, read, m, oreName] of rows) {
      if (!read) continue;
      if (!m.id && k.startsWith('badge') && !unknownBadge) { unknownBadge = k; M.equipRows.push({ k, label, read, id: 'custom', opts: [], ore: null, custom: true, use: true }); continue; }
      const g = m.id && GS.includes(k) ? ITEMS[m.id] : null;
      const oid = g ? matchOre(oreName, g) : null;
      M.equipRows.push({ k, label, read, id: m.id, opts: m.opts, ore: oid, oreRead: oreName || '', sure: m.sure, use: !!m.id });
      if (!m.id) M.warn.push(`${label} "${read}"을(를) 장비 목록에서 찾지 못했습니다. 직접 골라 주세요.`);
    }
    M.equipRows.filter(r => r.use && r.id).forEach(r => { plan.equip[r.k] = r.id; if (r.ore !== null) plan.ore[r.k] = r.ore; });
    if (unknownBadge) M.custom = { k: unknownBadge, name: M.equipRows.find(r => r.k === unknownBadge).read };
    // 수치가 화면에 없는 배지: 확인 창에서 스탯 입력
    M.bvSlots = M.equipRows.filter(r => r.use && r.k.startsWith('badge') && (r.custom || badgeVarKeys(ITEMS[r.id]))).map(r => r.k);
    M.bv = {};
    M.bvSlots.forEach(k => {
      const r = M.equipRows.find(x => x.k === k);
      M.bv[k] = bvIn && bvIn[k] ? bvIn[k].map(x => Object.assign({}, x)) : r.custom ? [] : badgeVarKeys(ITEMS[r.id]).map(f => ({ s: f, v: '' }));
    });
    M.bvAuto = false;
  }
  M.plan = plan;
  // 캐릭터 스탯: 상세 화면 값 그대로 / 장비 화면만 있으면 장비 스탯을 빼서 역산
  const base = {};
  if (st) SHOT_FIELDS.forEach(([f]) => { base[f] = nz(st[f]); });
  if (eq) {
    const empty = (M.bvSlots || []).filter(k => !M.bv[k].length || M.bv[k].some(r => r.v === '' || r.v === null));
    if (st) {
      // 둘 다 있으면: 화면 차이 - 아는 장비 스탯 = 수치를 모르는 배지 몫 → 그런 배지가 하나뿐이고 아직 입력 전이면 그 값으로 채움
      const z = {}; (M.bvSlots || []).forEach(k => { z[k] = M.bv[k].map(r => ({ s: r.s, v: 0 })); });
      const bonus0 = equipStatBonus(plan, s, z);
      const diff = {}; ['str', 'int', 'spd', 'luck', 'mp', 'end', 'spr'].forEach(f => { const a = nz(eq[f]), b = nz(st[f]); diff[f] = a === null || b === null ? null : a - b - bonus0[f]; });
      if (M.bvSlots.length === 1 && empty.length === 1 && !bvIn) {
        const k = M.bvSlots[0], r = M.equipRows.find(x => x.k === k);
        if (r.custom) M.bv[k] = ['str', 'int', 'spd', 'luck', 'mp', 'end', 'spr'].filter(f => diff[f]).map(f => ({ s: f, v: diff[f] }));
        else M.bv[k] = M.bv[k].map(x => ({ s: x.s, v: diff[x.s] === null || diff[x.s] === undefined ? '' : diff[x.s] }));
        M.bvAuto = true;
      } else if (!M.bvSlots.length) {
        const off = ['str', 'int', 'spd', 'luck'].filter(f => diff[f] !== null && diff[f] !== 0);
        if (off.length) M.info.push('장비 화면 스탯과 계산 결과가 다릅니다: ' + off.map(f => `${STATN[f]} ${diff[f] > 0 ? '+' : ''}${diff[f]}`).join(', ') + ' — 두 캡처가 같은 캐릭터·스타일인지 확인해 주세요.');
      }
      if (M.bvSlots.length > 1 && empty.length) M.warn.push('수치가 보이지 않는 배지가 2개라 화면 차이로 나눌 수 없습니다. 아래 "배지 스탯"에 실제 수치를 입력해 주세요.');
    } else {
      const bonus = equipStatBonus(plan, s, M.bv);
      ['str', 'int', 'spd', 'luck', 'mp'].forEach(f => { const v = nz(eq[f]); base[f] = v === null ? null : v - bonus[f]; });
      M.info.push('캐릭터 상세 화면이 없어 장비 변경 화면의 스탯에서 장비가 주는 스탯을 빼서 캐릭터 스탯을 정했습니다.');
      const curEmpty = (M.bvSlots || []).filter(k => !M.bv[k].length || M.bv[k].some(r => r.v === '' || r.v === null));
      if (curEmpty.length) M.warn.push('캐릭터 상세 화면(장비 해제)이 없어 ' + curEmpty.map(k => M.equipRows.find(x => x.k === k).read).join(', ') + '의 수치를 알 수 없습니다. 아래 "배지 스탯"에 수치를 입력하면 캐릭터 스탯이 다시 계산됩니다. (입력 전에는 0으로 계산)');
    }
  }
  SHOT_FIELDS.forEach(([f, label]) => { if (base[f] !== undefined && base[f] !== null) M.rows.push({ id: f, label, cur: $(f).value, val: base[f], use: true }); });
  { // 루나틱 솔선 기본값: 캐릭터 내구·정신(장비 제외). 장비 몫은 페이지가 장착 장비로 더함
    let e0 = null, s0 = null, how = '';
    if (st) { e0 = nz(st.end); s0 = nz(st.spr); }
    else if (eq) { const b = equipStatBonus(plan, s, M.bv); e0 = nz(eq.end) === null ? null : nz(eq.end) - b.end; s0 = nz(eq.spr) === null ? null : nz(eq.spr) - b.spr; how = ' (장비 화면에서 장비 몫을 뺌)'; }
    if (e0 !== null) M.rows.push({ id: 'solEnd', label: '내구 (장비 제외)' + how, cur: solBase ? solBase.end : '-', val: e0, use: true, sol: true });
    if (s0 !== null) M.rows.push({ id: 'solSpr', label: '정신 (장비 제외)' + how, cur: solBase ? solBase.spr : '-', val: s0, use: true, sol: true });
  }
  if (st && st.name) M.rows.push({ id: 'who', label: '캐릭터 이름', cur: $('who').value, val: String(st.name).trim(), use: true, text: true });
  if (bs) BOSS_FIELDS.forEach(([f, label, src]) => { const v = nz(bs[src]); if (v !== null) M.rows.push({ id: f, label: '보스 ' + label, cur: $(f).value, val: v, use: true }); });
  return M;
}

let shotExOpen = false;
const SHOT_EX = [
  ['캐릭터 상세', '— 장비를 모두 해제한 상태. 천명 수치가 보이는 화면 (필수 권장)'],
  ['장비 변경', '— 장비를 낀 상태 (선택). 장비와 배지·글래스터를 맞춰 넣습니다'],
  ['보스 스탯', '— 전투 화면 그대로 올리면 위쪽 상자만 읽습니다'],
];
function renderShot() {
  const box = $('shotBox'), M = shotModel;
  const thumbs = shotFiles.map((f, i) => `<span class="shot-th"><img alt="첨부 ${i + 1}" src="${f._url}"><button class="lx" type="button" data-shdel="${i}" aria-label="첨부 ${i + 1} 빼기">×</button>${shotStat[i] ? `<span class="shot-st${/읽지 못함/.test(shotStat[i]) ? ' bad' : ''}">${esc(shotStat[i])}</span>` : ''}</span>`).join('');
  let h = `<div class="shot-drop" id="shotDrop" tabindex="0">캐릭터 상세(장비 해제) · 보스 스탯 화면을 올리세요. 장비 변경 화면도 함께 올리면 장비까지 맞춰 넣습니다. <span class="shot-pick"><span class="btn solid" aria-hidden="true">사진 선택</span><input type="file" id="shotFile" accept="image/*" multiple aria-label="사진 선택"></span><span class="hint">PC에서는 끌어다 놓거나 붙여넣기(Ctrl+V)도 됩니다</span> <button class="btn" type="button" id="shotEx" aria-expanded="${shotExOpen}">${shotExOpen ? '예시 닫기' : '사진 예시'}</button></div>`;
  if (shotExOpen) h += `<div class="shot-ex">${SHOT_EX.map(([cap, note], i) => `<figure><img src="${SHOT_EX_IMG[i]}" alt="${esc(cap)} 예시"><figcaption><b>${esc(cap)}</b> ${esc(note)}</figcaption></figure>`).join('')}</div>`;
  if (shotFiles.length) h += `<div class="shot-ths">${thumbs}</div>`;
  if (shotAddErr.length) h += shotAddErr.map(w => `<div class="shot-warn">${esc(w)}</div>`).join('');
  h += `<div class="shot-act"><button class="btn solid" type="button" id="shotRead"${shotFiles.length && !shotCtl ? '' : ' disabled'}>${shotCtl ? '읽는 중…' : '읽기'}</button>${shotCtl ? '<button class="btn" type="button" id="shotStop">중지</button>' : ''}<button class="btn" type="button" id="shotClose">닫기</button><span class="hint" id="shotMsg"></span></div>`;
  if (M) {
    h += M.warn.map(w => `<div class="shot-warn">${esc(w)}</div>`).join('') + (shotRaw.length || shotDiag.length ? `<details class="hint"><summary>읽은 원본 보기 (문제 확인용)</summary><pre style="white-space:pre-wrap;font-size:11px">${esc(JSON.stringify({ 직접읽기: shotDiag, AI: shotRaw }, null, 1)).slice(0, 4000)}</pre></details>` : '') + M.info.map(w => `<div class="hint">${esc(w)}</div>`).join('');
    if (M.rows.length) h += `<table class="shot-tb"><thead><tr><th></th><th>항목</th><th>지금</th><th>넣을 값</th></tr></thead><tbody>${M.rows.map((r, i) => `<tr><td><input type="checkbox" data-shu="${i}"${r.use ? ' checked' : ''} aria-label="${esc(r.label)} 넣기"></td><td>${esc(r.label)}</td><td class="num">${esc(r.cur)}</td><td><input ${r.text ? 'type="text"' : 'type="number"'} data-shv="${i}" value="${esc(r.val)}" aria-label="${esc(r.label)} 넣을 값"></td></tr>`).join('')}</tbody></table>`;
    if (M.equipRows.length) h += `<table class="shot-tb"><thead><tr><th></th><th>칸</th><th>화면</th><th>장착할 장비</th></tr></thead><tbody>${M.equipRows.map((r, i) => {
      const sel = r.custom ? `<span class="hint">반복 획득 배지로 생성 (스탯은 아래에서)</span>`
        : r.opts.length > 1 ? `<select data-shq="${i}">${r.opts.map(id => `<option value="${id}"${id === r.id ? ' selected' : ''}>${esc(ITEMS[id].n)}${ITEMS[id].wt ? ' <' + esc(ITEMS[id].wt) + '>' : ''}${ITEMS[id].atk !== undefined ? ` (${ITEMS[id].atk}/${ITEMS[id].mag})` : ''}</option>`).join('')}</select>`
        : r.id ? esc(ITEMS[r.id].n) : '<span class="hint">찾지 못함</span>';
      const o = r.ore !== null && r.ore !== undefined && r.id && ITEMS[r.id] ? `<div class="hint">연성: ${esc(oreName(ITEMS[r.id], r.ore))}${r.oreRead && !r.ore ? ` ("${esc(r.oreRead)}" 못 찾음)` : ''}</div>` : '';
      return `<tr><td><input type="checkbox" data-she="${i}"${r.use ? ' checked' : ''}${r.id ? '' : ' disabled'} aria-label="${esc(r.label)} 장착"></td><td>${esc(r.label)}</td><td>${esc(r.read)}</td><td>${sel}${o}</td></tr>`;
    }).join('')}</tbody></table>`;
    if (M.bvSlots && M.bvSlots.length) {
      h += `<div class="shot-bv"><div class="sec-h" style="margin:8px 0 4px">배지 스탯 <span class="hint">화면에 수치가 안 나오는 배지${M.bvAuto ? ' · 두 화면 차이로 계산해 채움' : ''}</span></div>`;
      for (const k of M.bvSlots) {
        const r = M.equipRows.find(x => x.k === k);
        h += `<div class="shot-bvr"><b>${esc(r.label)}</b> <span class="hint">${esc(r.read)}${r.custom ? ' (반복 획득)' : ''}</span>`;
        h += M.bv[k].map((x, i) => `<span class="shot-bvi"><select data-sbs="${k}:${i}" aria-label="스탯">${BADGE_STATS.map(f => `<option value="${f}"${f === x.s ? ' selected' : ''}>${BADGE_LABEL[f]}</option>`).join('')}</select><input type="number" data-sbv="${k}:${i}" value="${x.v === null ? '' : esc(x.v)}" placeholder="수치" aria-label="${BADGE_LABEL[x.s]} 수치"><button class="lx" type="button" data-sbd="${k}:${i}" aria-label="빼기">×</button></span>`).join('');
        h += `<button class="btn" type="button" data-sba="${k}" style="padding:1px 8px">+ 스탯</button></div>`;
      }
      h += `</div>`;
    }
    if (M.rows.length || M.equipRows.length) h += `<div class="shot-act"><button class="btn solid" type="button" id="shotApply">체크한 항목 적용</button></div>`;
  }
  box.innerHTML = h;
}

// 보내기 전에 JPEG(긴 변 최대 2000px)로 다시 저장: HEIC·큰 PNG·특이한 형식도 읽을 수 있게
async function shotNormalize(f) {
  try {
    const bmp = await createImageBitmap(f);
    const sc = Math.min(1, 2000 / Math.max(bmp.width, bmp.height));
    const c = document.createElement('canvas'); c.width = Math.round(bmp.width * sc); c.height = Math.round(bmp.height * sc);
    c.getContext('2d').drawImage(bmp, 0, 0, c.width, c.height); bmp.close && bmp.close();
    const blob = await new Promise(r => c.toBlob(r, 'image/jpeg', 0.9));
    return blob || f;
  } catch (e) {
    try {   // createImageBitmap이 못 여는 형식은 <img>로 한 번 더
      const url = URL.createObjectURL(f), img = new Image(); img.src = url; await img.decode();
      const sc = Math.min(1, 2000 / Math.max(img.naturalWidth, img.naturalHeight));
      const c = document.createElement('canvas'); c.width = Math.round(img.naturalWidth * sc); c.height = Math.round(img.naturalHeight * sc);
      c.getContext('2d').drawImage(img, 0, 0, c.width, c.height); URL.revokeObjectURL(url);
      return (await new Promise(r => c.toBlob(r, 'image/jpeg', 0.9))) || f;
    } catch (e2) { return f; }
  }
}
// 고르는 즉시 파일 내용을 메모리로 복사: 휴대폰에서 나중에 읽으면 '파일을 읽을 수 없음'이 나는 경우가 있어서
let shotAddErr = [];
async function shotAdd(files) {
  const lim = shotSample && shotSample._lim; shotAddErr = [];
  for (const f of files) {
    if (!f || (f.type && !/^image\//.test(f.type) && !/\.(jpe?g|png|webp|gif|heic|heif)$/i.test(f.name || ''))) continue;
    if (lim && lim.maxCount && shotFiles.length >= lim.maxCount) break;
    const key = [f.name, f.size, f.lastModified].join('|');
    if (shotFiles.some(x => x._key === key)) { shotAddErr.push(`${f.name || '사진'}: 이미 올린 사진이라 건너뜀`); continue; }
    let g;
    try { const buf = await f.arrayBuffer(); g = new File([buf], f.name || 'image.jpg', { type: f.type || 'image/jpeg' }); }
    catch (e) { shotAddErr.push(`${f.name || '사진'}: 파일을 열 수 없습니다. 갤러리 앱에서 사진을 기기에 저장(다운로드)한 뒤 다시 골라 주세요.`); continue; }
    g._key = key; g._url = URL.createObjectURL(g); shotFiles.push(g); shotStat = [];
  }
  shotModel = null; renderShot();
}

